contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will attempt to call airDrop (no params). The test checks that either the call reverts,
    // or it succeeds and tokenBalance[this] becomes exactly 20 (from 0) and was 0 before.
    function run() public payable {
        // observe balance before
        uint before = c.tokenBalance(address(this));

        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = c.tokenBalance(address(this));

        // General property:
        // If the call reverted, no further requirement. If it succeeded, then before must have been 0
        // (due to hasNoBalance) and after == before + 20.
        assert(reverted || (before == 0 && after == before + 20));
    }

    receive() external payable { }
}

