contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an address parameter 'caller' to simulate different msg.sender targets by using
    // a helper: the test contract itself is the caller when invoking c.airDrop(), so the
    // supportsToken modifier expects Bank(msg.sender).supportsToken(), which will call
    // Bank(address(this)).supportsToken(). To satisfy that, the test contract will deploy no
    // Bank, but we can pass any address parameter only to read initial balances; instead we
    // observe behavior when this contract (the caller) either satisfies or doesn't satisfy
    // supportsToken by controlling whether address(this) has a supportsToken() returning the
    // correct bytes32 — impossible to change here. Therefore we assert a general relation that
    // if the call succeeds then preconditions (balance==0 and supportsToken matched) must have
    // held, and the balance increases by 20; otherwise balance unchanged.

    // Single public test function with inputs unused except an arbitrary uint to satisfy template
    function run(uint dummy) public payable {
        require(true);

        // Read pre-state: token balance of this contract (msg.sender for calls will be this test contract)
        uint before = c.tokenBalance(address(this));

        // Attempt the call and capture whether it reverted
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint after = c.tokenBalance(address(this));

        // General rule (one assert): if the call reverted then balance is unchanged; if it succeeded then
        // before must have been 0 and after == before + 20 and contract-level _locked reset to false.
        // We cannot access internal _locked directly; but SmartFix._locked is public, so we can read it via c._locked().
        bool lockedFalse = c._locked() == false;

        assert(
            (reverted && after == before) ||
            (!reverted && before == 0 && after == before + 20 && lockedFalse)
        );
    }

    // provide receive to accept Ether if needed
    receive() external payable {}
}

