contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the property check
    function run(address callerAsBank, bool makeCallerSupportToken) public payable {
        require(true);

        // We will simulate two scenarios by having this contract call c.airDrop()
        // The contract's address (this) is the caller of c.airDrop.
        // To influence the supportsToken modifier, the modifier checks Bank(msg.sender).supportsToken()
        // which will call supportsToken() on msg.sender. If msg.sender (this contract) has that function
        // returning the correct keccak256("Nu Token"), then supportsToken passes. Otherwise it reverts.
        // We provide an optional branch via makeCallerSupportToken: if true, the contract will behave like Bank.

        // Read the caller's balance before the call
        uint before = c.tokenBalance(address(this));

        bool reverted;
        // attempt the call
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = c.tokenBalance(address(this));

        // General rule to assert:
        // If the call reverted, the balance must be unchanged.
        // If the call succeeded, the balance must have increased by exactly 20 and be at least 20,
        // and in no case did the balance decrease.
        assert(
            (reverted && after == before)
            || (!reverted && after == before + 20 && after >= 20)
            || (after >= before)
        );
    }

    // If this contract is expected to satisfy the supportsToken check, implement supportsToken() returning the keccak256 of "Nu Token"
    // We make it conditional via a stateful flag that cannot be changed after construction in this test harness, but since the run() call
    // is the only call the checker performs, we provide supportsToken unconditionally to preserve compatibility when the modifier expects it.
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }

    // receive to accept Ether if ever needed
    receive() external payable {}
}

