contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call run with a boolean indicating whether msg.sender (this test contract)
    // should be treated as Bank by the supportsToken modifier. Since supportsToken
    // compares keccak256("Nu Token") to Bank(msg.sender).supportsToken(), the
    // only way for that to succeed is that msg.sender implements that exact function.
    // Our InvMutTest does NOT implement supportsToken, so calls from this contract
    // will fail the supportsToken requirement. To exercise both outcomes, we use
    // an address parameter `caller` which should be an address of a contract that
    // has supportsToken() matching the token name. However, per constraints, calls
    // to c are made with msg.sender == address(this). Therefore to reach the success
    // case we rely on the fact that the checker deploys a fresh C and then calls run
    // once; we can still assert a general property that covers both revert and success.

    function run() public payable {
        require(true);

        // Read balance before
        uint before = c.tokenBalance(address(this));

        // Attempt the call and record if it reverted
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balance after
        uint after = c.tokenBalance(address(this));

        // Also observe that the SmartFix's _locked should be false after the call
        // The _locked variable is public in SmartFix, so there is an auto-generated getter
        bool locked = SmartFix(address(c))._locked();

        // General rule:
        // - If the call reverted then balance must be unchanged.
        // - If the call did not revert then balance increased by exactly 20.
        // - In all cases the reentrancy lock (_locked) is false at the end.
        assert((reverted && after == before || !reverted && after == before + 20) && locked == false);
    }

    // Provide a fallback so this contract can be treated like a contract by C if needed.
    receive() external payable {}
}

